  /* \u69FD\u4F4D\u5BB9\u5668\u5951\u7EA6:\u666E\u901A\u6D41 + 100% \u9AD8(schedule \u9875\u9762\u540C\u6B3E),\u4E0D\u80FD\u7EDD\u5BF9\u5B9A\u4F4D */
